"""Abstraction from the Redis content written by rq to the state a user of rq sees.

Business-level state:
  queues  : per queue, the jobs waiting in it (in order), the jobs a worker has
            just taken but not yet started, and the job registries
            (started / finished / failed / deferred / scheduled / canceled).
  jobs    : per existing job, its status, queue, description, configuration
            (timeouts, TTLs, retries, repeats, callbacks, dependencies, group),
            whether it is set to expire, its current executions and its results.
  workers : per worker, its state, the job it is working on and its counters.

Invariants are business rules that should hold whenever rq is used correctly.
A False value means the state is inconsistent from the user's point of view.
Example: a job that was canceled while running but then finished anyway is
both "canceled" and "finished".

Known rq windows are tolerated:
  - a job is in the started registry, with status "queued", while a worker
    picks it up;
  - a job being retried after an interval is marked "scheduled" just before
    its execution is cleaned up;
  - a repeating job stays in the finished registry while it waits for its
    next run.
"""

import json

STATUSES = (
    "created", "queued", "started", "deferred", "scheduled",
    "finished", "failed", "stopped", "canceled",
)

RESULT_TYPES = {
    "1": "successful",
    "2": "failed",
    "3": "stopped",
    "4": "retried",
    "5": "max_retries_exceeded",
}

REGISTRY_PREFIXES = (
    ("rq:wip:", "started"),
    ("rq:finished:", "finished"),
    ("rq:failed:", "failed"),
    ("rq:deferred:", "deferred"),
    ("rq:scheduled:", "scheduled"),
    ("rq:canceled:", "canceled"),
)

QUEUE_SECTIONS = (
    "waiting", "being_picked_up", "started", "finished",
    "failed", "deferred", "scheduled", "canceled",
)


# ----------------------------------------------------------------- helpers

def _s(x):
    if x is None:
        return ""
    return x if isinstance(x, str) else str(x)


def _opt(x):
    """Empty string means 'not set' in rq hashes."""
    x = _s(x)
    return x if x != "" else None


def _int(x):
    x = _s(x).strip()
    if x == "":
        return None
    try:
        return int(x)
    except ValueError:
        try:
            return int(float(x))
        except ValueError:
            return x


def _entry(e, t):
    if isinstance(e, dict) and e.get("t") == t:
        return e.get("v")
    return None


def _zmembers(v):
    out = []
    if isinstance(v, list):
        for item in v:
            if isinstance(item, (list, tuple)) and item:
                out.append(_s(item[0]))
            elif isinstance(item, str):
                out.append(item)
    return out


def _list(v):
    return [_s(x) for x in v] if isinstance(v, list) else []


def _hash(v):
    return v if isinstance(v, dict) else {}


def _job_of(composite):
    composite = _s(composite)
    return composite.split(":", 1)[0]


def _exec_of(composite):
    parts = _s(composite).split(":", 1)
    return parts[1] if len(parts) > 1 else ""


def _json_list(x):
    x = _s(x)
    if not x:
        return None
    try:
        v = json.loads(x)
    except (ValueError, TypeError):
        return None
    if isinstance(v, list):
        return [_s(i) for i in v]
    return None


def _exc_name(x):
    x = _s(x)
    if x.startswith("<exc:") and x.endswith(">"):
        return x[5:-1]
    return x or None


# ------------------------------------------------------------- the model

def _model(snap):
    snap = snap if isinstance(snap, dict) else {}
    queues = {}
    known_queues = set()
    job_hashes = {}
    job_ttl = {}
    dependents = {}
    dependencies_set = {}
    exec_ids = {}        # job -> set(execution id)
    exec_workers = {}    # job -> {execution id: worker}
    results = {}         # job -> [field dict]
    workers = {}
    started_entries = []  # (queue, job id, execution id)

    def q(name):
        if name not in queues:
            queues[name] = {k: [] for k in QUEUE_SECTIONS}
        return queues[name]

    for key in sorted(snap, key=_s):
        k = _s(key)
        e = snap.get(key)
        try:
            if k == "rq:queues":
                for m in _list(_entry(e, "set")):
                    if m.startswith("rq:queue:"):
                        name = m[len("rq:queue:"):]
                        known_queues.add(name)
                        q(name)
                continue

            if k.startswith("rq:queue:"):
                v = _entry(e, "list")
                if v is None:
                    continue  # e.g. intermediate first_seen markers (strings)
                rest = k[len("rq:queue:"):]
                if rest.endswith(":intermediate"):
                    q(rest[: -len(":intermediate")])["being_picked_up"].extend(_list(v))
                elif ":" not in rest or True:
                    q(rest)["waiting"].extend(_list(v))
                continue

            matched = False
            for prefix, kind in REGISTRY_PREFIXES:
                if k.startswith(prefix):
                    matched = True
                    v = _entry(e, "zset")
                    if v is None:
                        break
                    name = k[len(prefix):]
                    members = _zmembers(v)
                    if kind == "started":
                        for m in members:
                            started_entries.append((name, _job_of(m), _exec_of(m)))
                        q(name)["started"].extend(_job_of(m) for m in members)
                    else:
                        q(name)[kind].extend(members)
                    break
            if matched:
                continue

            if k.startswith("rq:executions:"):
                j = k[len("rq:executions:"):]
                exec_ids.setdefault(j, set()).update(_zmembers(_entry(e, "zset")))
                continue

            if k.startswith("rq:execution:"):
                h = _entry(e, "hash")
                if h is None:
                    continue
                rest = k[len("rq:execution:"):]
                j, x = _job_of(rest), _exec_of(rest)
                h = _hash(h)
                x = _s(h.get("id")) or x
                exec_ids.setdefault(j, set()).add(x)
                exec_workers.setdefault(j, {})[x] = _opt(h.get("worker_name"))
                continue

            if k.startswith("rq:results:"):
                v = _entry(e, "stream")
                if isinstance(v, list):
                    results[k[len("rq:results:"):]] = [r for r in v if isinstance(r, dict)]
                continue

            if k.startswith("rq:job::") and k.endswith(":dependencies"):
                j = k[len("rq:job::"): -len(":dependencies")]
                dependencies_set[j] = _list(_entry(e, "set"))
                continue

            if k.startswith("rq:job:"):
                rest = k[len("rq:job:"):]
                if rest.endswith(":dependents") and rest.count(":") == 1:
                    dependents[rest[: -len(":dependents")]] = _list(_entry(e, "set"))
                    continue
                if rest and ":" not in rest:
                    h = _entry(e, "hash")
                    if h is not None:
                        job_hashes[rest] = _hash(h)
                        job_ttl[rest] = bool(e.get("ttl")) if isinstance(e, dict) else False
                continue

            if k.startswith("rq:worker:"):
                rest = k[len("rq:worker:"):]
                h = _entry(e, "hash")
                if h is None or not rest or ":" in rest:
                    continue
                h = _hash(h)
                qs = _opt(h.get("queues"))
                workers[rest] = {
                    "state": _opt(h.get("state")),
                    "current_job": _opt(h.get("current_job")),
                    "successful_job_count": _int(h.get("successful_job_count")) or 0,
                    "failed_job_count": _int(h.get("failed_job_count")) or 0,
                    "queues": sorted(x for x in qs.split(",") if x) if qs else [],
                }
                continue
        except Exception:  # never raise on odd snapshots
            continue

    jobs = {}
    for j in sorted(job_hashes):
        h = job_hashes[j]
        origin = _opt(h.get("origin"))
        if origin is not None:
            q(origin)
        deps = _json_list(h.get("dependency_ids"))
        if deps is None:
            d = _opt(h.get("dependency_id"))
            deps = [d] if d else []
        deps = sorted(set(deps) | set(dependencies_set.get(j, [])))

        res = []
        for r in results.get(j, []):
            t = _s(r.get("type"))
            item = {
                "type": RESULT_TYPES.get(t, "type_" + t if t else "unknown"),
                "worker": _opt(r.get("worker_name")),
                "execution": _opt(r.get("execution_id")),
            }
            if "return_value" in r:
                item["return_value"] = _s(r.get("return_value"))
            if "exc_string" in r:
                item["exception"] = _exc_name(r.get("exc_string"))
            res.append(item)

        execs = [
            {"id": x, "worker": exec_workers.get(j, {}).get(x)}
            for x in sorted(exec_ids.get(j, set()))
        ]

        jobs[j] = {
            "status": _opt(h.get("status")) or "created",
            "queue": origin,
            "description": _opt(h.get("description")),
            "worker": _opt(h.get("worker_name")),
            "enqueued": _opt(h.get("enqueued_at")) is not None,
            "started": _opt(h.get("started_at")) is not None,
            "ended": _opt(h.get("ended_at")) is not None,
            "depends_on": deps,
            "dependents": sorted(set(dependents.get(j, []))),
            "allow_dependency_failures": bool(_int(h.get("allow_dependency_failures")) or 0),
            "timeout": _int(h.get("timeout")),
            "result_ttl": _int(h.get("result_ttl")),
            "failure_ttl": _int(h.get("failure_ttl")),
            "ttl": _int(h.get("ttl")),
            "retries_left": _int(h.get("retries_left")),
            "retries_done": _int(h.get("number_of_retries")),
            "repeats_left": _int(h.get("repeats_left")),
            "repeating": _opt(h.get("repeats_left")) is not None
                         or _opt(h.get("repeat_intervals")) is not None,
            "on_success": _opt(h.get("success_callback_name")),
            "on_failure": _opt(h.get("failure_callback_name")),
            "on_stopped": _opt(h.get("stopped_callback_name")),
            "group": _opt(h.get("group_id")),
            "expires": job_ttl.get(j, False),
            "executions": execs,
            "results": res,
        }

    for name, sec in queues.items():
        for kind in QUEUE_SECTIONS:
            if kind not in ("waiting", "being_picked_up"):
                sec[kind] = sorted(set(sec[kind]))

    return {
        "queues": {n: queues[n] for n in sorted(queues)},
        "known_queues": sorted(known_queues),
        "jobs": jobs,
        "workers": {w: workers[w] for w in sorted(workers)},
        "started_entries": sorted(started_entries),
    }


# ------------------------------------------------------------------ API

def abstract(snap: dict) -> dict:
    """Business-level state, as {variable name: JSON-serialisable value}."""
    try:
        m = _model(snap)
    except Exception:
        return {"queues": {}, "jobs": {}, "workers": {}}
    jobs = m["jobs"]
    out_jobs = {}
    for j, r in jobs.items():
        rr = dict(r)
        rr.pop("repeating", None)
        out_jobs[j] = rr
    return {
        "queues": m["queues"],
        "jobs": out_jobs,
        "workers": m["workers"],
    }


def invariants(snap: dict) -> dict:
    """Business invariants, as {invariant name: bool}; True means it holds."""
    try:
        m = _model(snap)
    except Exception:
        return {}
    jobs, queues, workers = m["jobs"], m["queues"], m["workers"]
    known_queues = set(m["known_queues"])

    def status(j):
        return jobs[j]["status"] if j in jobs else None

    def listed(j, kind):
        qn = jobs[j]["queue"]
        return qn is not None and qn in queues and j in queues[qn][kind]

    inv = {}

    inv["every_job_has_a_known_status"] = all(r["status"] in STATUSES for r in jobs.values())

    # --- waiting in queues
    waiting = [(qn, j) for qn, sec in queues.items() for j in sec["waiting"]]
    inv["waiting_jobs_exist"] = all(j in jobs for _, j in waiting)
    inv["waiting_jobs_are_queued"] = all(status(j) == "queued" for _, j in waiting if j in jobs)
    ids = [j for _, j in waiting]
    inv["job_waits_at_most_once"] = len(ids) == len(set(ids))
    inv["job_waits_in_its_own_queue"] = all(jobs[j]["queue"] == qn for qn, j in waiting if j in jobs)
    inv["queues_with_waiting_jobs_are_known"] = all(
        qn in known_queues for qn, sec in queues.items() if sec["waiting"]
    )

    # --- every status has its home
    inv["queued_jobs_are_waiting_in_their_queue"] = all(
        listed(j, "waiting") or listed(j, "being_picked_up") or listed(j, "started")
        for j in jobs if status(j) == "queued"
    )
    inv["running_jobs_are_in_started_registry"] = all(
        listed(j, "started") for j in jobs if status(j) == "started"
    )
    inv["finished_jobs_are_in_finished_registry"] = all(
        listed(j, "finished") for j in jobs if status(j) == "finished"
    )
    inv["failed_and_stopped_jobs_are_in_failed_registry"] = all(
        listed(j, "failed") for j in jobs if status(j) in ("failed", "stopped")
    )
    inv["deferred_jobs_are_in_deferred_registry"] = all(
        listed(j, "deferred") for j in jobs if status(j) == "deferred"
    )
    inv["scheduled_jobs_are_in_scheduled_registry"] = all(
        listed(j, "scheduled") for j in jobs if status(j) == "scheduled"
    )
    inv["canceled_jobs_are_in_canceled_registry"] = all(
        listed(j, "canceled") for j in jobs if status(j) == "canceled"
    )

    # --- registries hold only jobs in the matching status
    allowed = {
        "being_picked_up": {"queued", "failed"},
        "started": {"queued", "started", "scheduled"},
        "finished": {"finished"},
        "failed": {"failed", "stopped"},
        "deferred": {"deferred"},
        "scheduled": {"scheduled"},
        "canceled": {"canceled"},
    }
    ok = True
    for qn, sec in queues.items():
        for kind, statuses in allowed.items():
            for j in sec[kind]:
                if j not in jobs:
                    continue
                if kind == "finished" and jobs[j]["repeating"]:
                    continue
                if status(j) not in statuses or jobs[j]["queue"] not in (None, qn):
                    ok = False
    inv["jobs_in_registries_match_their_status"] = ok

    # --- running
    per_job = {}
    for _, j, _x in m["started_entries"]:
        per_job[j] = per_job.get(j, 0) + 1
    inv["job_runs_at_most_once_at_a_time"] = all(c <= 1 for c in per_job.values())

    holders = {}
    for w, r in workers.items():
        if r["current_job"]:
            holders[r["current_job"]] = holders.get(r["current_job"], 0) + 1
    inv["running_job_has_at_most_one_worker"] = all(c <= 1 for c in holders.values())
    inv["worker_current_job_is_running"] = all(
        status(r["current_job"]) in ("started", "scheduled")
        for r in workers.values()
        if r["current_job"] and r["current_job"] in jobs
    )
    inv["idle_workers_have_no_current_job"] = all(
        not r["current_job"] for r in workers.values() if r["state"] == "idle"
    )

    # --- results
    def latest(j):
        res = jobs[j]["results"]
        return res[-1]["type"] if res else None

    inv["finished_jobs_have_a_successful_latest_result"] = all(
        latest(j) == "successful" for j in jobs if status(j) == "finished"
    )
    inv["failed_jobs_have_a_failure_as_latest_result"] = all(
        latest(j) is not None and latest(j) not in ("successful", "retried")
        for j in jobs if status(j) == "failed"
    )

    return inv
